INSERT INTO system_mail_template (name, code, account_id, nickname, title, content, params, status, remark, creator, create_time, updater, update_time, deleted) VALUES
('博客-注册验证码', 'blog-register-code', 1, 'Ruyu-Blog', '欢迎注册Ruyu-Blog', '<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><title>欢迎邮件</title><style>.butt_to:hover{background:linear-gradient(135deg,#f02fc2,#6094ea)!important;color:#fff!important;box-shadow:0 0 10px rgba(0,0,0,.4)!important}</style></head><body><div style="text-align:center;font-size:20px;color:#333;border-radius:1rem;min-height:100vh;padding:0 2rem;background:linear-gradient(135deg,#f02fc2,#6094ea)"><div style="width:150px;height:150px;margin:0 auto;padding-top:2rem"><img src="https://image.kuailemao.xyz/blog/websiteInfo/avatar/52e4b3e9-b1e0-4e9b-ab6e-4effc237ab1a.jpg" alt="头像" style="width:100%;height:100%;border-radius:40%;box-shadow:0 0 10px rgba(0,0,0,.4)"></div><div style="margin-top:20px;display:flex;justify-content:center;align-items:center"><div>欢迎注册 <span style="color:#0653e8;font-weight:bold;font-size:25px">Ruyu-Blog</span></div><div style="margin-left:10px">&nbsp;&nbsp; 一个全开源免费的个人博客网站</div></div><p style="margin:1rem 0">您的邮件验证码为：<span style="color:#f06595;font-weight:bold;font-size:1.5rem">{code}</span></p><p>有效时间为 {expirationTime}，为了保障您的安全，请勿向他人泄露验证码信息。如非本人操作，请忽略此邮件。</p><div style="display:flex;justify-content:space-around;align-items:center;margin-top:2rem"><a href="{toUrl}"><div class="butt_to" style="width:200px;height:50px;line-height:50px;text-align:center;font-size:20px;font-weight:bold;color:#333;background:#fff;border-radius:1rem;margin:0 auto">立即前往</div></a><a href="{openSourceAddress}"><div class="butt_to" style="width:200px;height:50px;line-height:50px;text-align:center;font-size:20px;font-weight:bold;color:#333;background:#fff;border-radius:1rem;margin:0 auto">给个Star</div></a></div><div style="text-align:center;padding:1rem 0;font-size:15px">此为系统邮件，请勿回复。</div></div></body></html>', '["code","expirationTime","toUrl","openSourceAddress"]', 0, '用户注册时发送邮箱验证码', '1', NOW(), '1', NOW(), 0);
INSERT INTO system_mail_template (name, code, account_id, nickname, title, content, params, status, remark, creator, create_time, updater, update_time, deleted) VALUES
