INSERT INTO system_mail_template (name, code, account_id, nickname, title, content, params, status, remark, creator, create_time, updater, update_time, deleted) VALUES
('博客-友链申请通知', 'blog-link-apply', 1, 'Ruyu-Blog', 'Ruyu-Blog友链申请通知', '<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><title>友链申请</title><style>.butt_to:hover{background:linear-gradient(135deg,#f02fc2,#6094ea)!important;color:#fff!important;box-shadow:0 0 10px rgba(0,0,0,.4)!important}</style></head><body><div style="display:flex;justify-content:center;align-items:center;flex-direction:column;font-size:20px;color:#333;border-radius:1rem;min-height:100vh;padding:0 2rem;background:linear-gradient(135deg,#f02fc2,#6094ea)"><div style="height:100%;padding:0 2rem"><div style="width:150px;height:150px;margin:0 auto;padding-top:2rem"><img src="https://image.kuailemao.xyz/blog/websiteInfo/avatar/52e4b3e9-b1e0-4e9b-ab6e-4effc237ab1a.jpg" alt="头像" style="width:100%;height:100%;border-radius:40%;box-shadow:0 0 10px rgba(0,0,0,.4)"></div><div style="margin-top:20px;display:flex;justify-content:center;align-items:center"><div><span style="color:#fff;font-weight:bold;font-size:25px">站长大人，有新的友链申请</span></div></div><div style="display:flex;justify-content:start;align-items:start;width:100%;margin-top:3rem"><div style="font-weight:bold;color:#000;font-size:18px;margin-left:1rem">申请信息如下：</div></div><div style="margin:1rem 0;display:flex;flex-direction:column;align-items:start;border:2px solid #ccc;padding:1rem;border-radius:1rem"><div><span style="font-weight:bold">网站名称：</span><span>{name}</span></div><div style="margin-top:.5rem"><span style="font-weight:bold">网站地址：</span><span><a href="{url}" style="text-decoration:none">{url}</a></span></div><div style="margin-top:.5rem"><span style="font-weight:bold">网站描述：</span><span>{description}</span></div><div style="margin-top:.5rem;display:flex;justify-content:center;align-items:center"><div><span style="font-weight:bold">背景图片：</span></div><div><img style="border-radius:1rem" width="200px" src="{background}" alt="网站地址"></div></div><div style="margin-top:.5rem"><span style="font-weight:bold">邮箱地址：</span><span>{linkEmail}</span></div></div><p style="font-size:15px;color:#630000">邮箱审核按钮 <span style="font-weight:bold">7</span> 天有效，失效后只能前往后台审核</p><div style="display:flex;justify-content:space-around;align-items:center;margin:2rem 0"><a href="{toUrl}"><div class="butt_to" style="width:200px;height:50px;line-height:50px;text-align:center;font-size:20px;font-weight:bold;color:#333;background:#fff;border-radius:1rem;margin:0 auto">前台查看</div></a><a href="{verifyCode}" style="margin-left:5rem"><div class="butt_to" style="width:200px;height:50px;line-height:50px;text-align:center;font-size:20px;font-weight:bold;color:#333;background:#fff;border-radius:1rem;margin:0 auto">审核通过</div></a></div><div style="text-align:center;padding-bottom:1rem;font-size:15px">此为系统邮件，请勿回复。</div></div></div></body></html>', '["name","url","description","background","linkEmail","toUrl","verifyCode"]', 0, '有用户申请友链时通知站长', '1', NOW(), '1', NOW(), 0);
INSERT INTO system_mail_template (name, code, account_id, nickname, title, content, params, status, remark, creator, create_time, updater, update_time, deleted) VALUES
('博客-友链审核通过', 'blog-link-pass', 1, 'Ruyu-Blog', 'Ruyu-Blog友链审核通知', '<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><title>友链审核通过</title><style>.butt_to:hover{background:linear-gradient(135deg,#f02fc2,#6094ea)!important;color:#fff!important;box-shadow:0 0 10px rgba(0,0,0,.4)!important}</style></head><body><div style="text-align:center;font-size:20px;color:#333;border-radius:1rem;min-height:100vh;padding:0 2rem;background:linear-gradient(135deg,#f02fc2,#6094ea)"><div style="width:150px;height:150px;margin:0 auto;padding-top:2rem"><img src="https://image.kuailemao.xyz/blog/websiteInfo/avatar/52e4b3e9-b1e0-4e9b-ab6e-4effc237ab1a.jpg" alt="头像" style="width:100%;height:100%;border-radius:40%;box-shadow:0 0 10px rgba(0,0,0,.4)"></div><div style="margin-top:20px;display:flex;justify-content:center;align-items:center"><div>欢迎访问 <span style="color:#0653e8;font-weight:bold;font-size:25px">Ruyu-Blog</span></div><div style="margin-left:10px">&nbsp;&nbsp; 一个全开源免费的个人博客网站</div></div><div style="font-weight:bold;color:#000;font-size:22px;margin:2rem 0">您的友链申请已经通过</div><div>快去看看吧o(*￣▽￣*)ブ</div><div style="display:flex;justify-content:space-around;align-items:center;margin-top:2rem"><a href="{toUrl}"><div class="butt_to" style="width:200px;height:50px;line-height:50px;text-align:center;font-size:20px;font-weight:bold;color:#333;background:#fff;border-radius:1rem;margin:0 auto">立即前往</div></a><a href="{openSourceAddress}"><div class="butt_to" style="width:200px;height:50px;line-height:50px;text-align:center;font-size:20px;font-weight:bold;color:#333;background:#fff;border-radius:1rem;margin:0 auto">给个Star</div></a></div><div style="text-align:center;padding:1rem 0;font-size:15px">此为系统邮件，请勿回复。</div></div></body></html>', '["toUrl","openSourceAddress"]', 0, '友链申请审核通过后通知申请人', '1', NOW(), '1', NOW(), 0);
