"border-radius:5px;background:#C0C4CC" width="50px" height="50px" src="{avatar}" alt="头像"></div><div style="margin-left:10px"><div style="display:flex"><div style="font-size:17px;font-weight:bold">{nickname}</div><div style="margin-left:20px"><span style="font-size:13px">{time}</span></div></div><div style="background:#F2F2F3;padding:.8rem;border-radius:10px;font-size:17px">{content}</div></div></div></div><div style="display:flex;justify-content:space-around;align-items:center;margin:2rem 0"><a href="{toUrl}"><div class="butt_to" style="width:200px;height:50px;line-height:50px;text-align:center;font-size:20px;font-weight:bold;color:#333;background:#fff;border-radius:1rem;margin:0 auto">前往查看</div></a></div><div style="text-align:center;padding-bottom:1rem;font-size:15px">此为系统邮件，请勿回复。</div></div></div></body></html>', '["commentTypeLabel","contentTitleLabel","title","urlLabel","url","avatar","nickname","time","content","toUrl"]', 0, '有新评论时通知作者/站长', '1', NOW(), '1', NOW(), 0);
