alt="头像"></div><div style="margin-left:10px"><div style="display:flex"><div style="font-size:17px;font-weight:bold">{replyNickname}</div><div style="margin-left:20px"><span style="font-size:13px">{replyTime}</span></div></div><div style="background:#F2F2F3;padding:.8rem;border-radius:10px;font-size:17px">{replyContent}</div></div></div><hr style="margin-left:50px;background-color:#DCDFE6;height:1px;border:none"><div style="display:flex;margin-left:50px;margin-top:20px"><div style="font-weight:bold;width:50px;height:50px;border:1px solid #ccc;border-radius:5px"><img style="border-radius:5px;background:#C0C4CC" width="50px" height="50px" src="{avatar}" alt="头像"></div><div style="margin-left:10px"><div style="display:flex"><div style="font-size:17px;font-weight:bold">{nickname}</div><div style="margin-left:20px"><span style="font-size:13px">{time}</span></div></div><div style="background:#F2F2F3;padding:.8rem;border-radius:10px;font-size:17px"><div style="font-weight:bold;color:#F49494">回复 @{replyNickname}</div><div style="margin-top:10px">{content}</div></div></div></div></div></div><div style="display:flex;justify-content:space-around;align-items:center;margin:2rem 0"><a href="{toUrl}"><div class="butt_to" style="width:200px;height:50px;line-height:50px;text-align:center;font-size:20px;font-weight:bold;color:#333;background:#fff;border-radius:1rem;margin:0 auto">前往查看</div></a></div><div style="text-align:center;padding-bottom:1rem;font-size:15px">此为系统邮件，请勿回复。</div></div></div></body></html>', '["replyTypeLabel","title","urlLabel","url","replyAvatar","replyNickname","replyTime","replyContent","avatar","nickname","time","content","toUrl"]', 0, '有人回复评论时通知被回复人', '1', NOW(), '1', NOW(), 0);
INSERT INTO system_mail_template (name, code, account_id, nickname, title, content, params, status, remark, creator, create_time, updater, update_time, deleted) VALUES
('博客-留言通知', 'blog-message-notify', 1, 'Ruyu-Blog', 'Ruyu-Blog有新的留言', '<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><title>留言通知</title><style>.butt_to:hover{background:linear-gradient(135deg,#f02fc2,#6094ea)!important;color:#fff!important;box-shadow:0 0 10px rgba(0,0,0,.4)!important}</style></head><body><div style="display:flex;justify-content:center;align-items:center;flex-direction:column;font-size:20px;color:#333;border-radius:1rem;min-height:100vh;width:100%;background:linear-gradient(135deg,#f02fc2,#6094ea)"><div style="height:100%;width:100%;display:flex;flex-direction:column;align-items:center;justify-content:center"><div style="width:150px;height:150px;margin:0 auto;padding-top:2rem"><img src="https://image.kuailemao.xyz/blog/websiteInfo/avatar/52e4b3e9-b1e0-4e9b-ab6e-4effc237ab1a.jpg" alt="头像" style="width:100%;height:100%;border-radius:40%;box-shadow:0 0 10px rgba(0,0,0,.4)"></div><div style="margin-top:20px;margin-bottom:40px;display:flex;justify-content:center;align-items:center"><div style="display:flex;flex-direction:column;align-items:center"><span style="color:#fff;font-weight:bold;font-size:25px;margin-bottom:20px">Ruyu-Blog</span><span style="color:#fff;font-weight:bold;font-size:25px">有新的留言</span></div></div><div style="margin:1rem 0;width:90%;display:flex;justify-content:center;align-items:center"><div style="width:95%;height:auto;min-height:200px;border:1px solid #E4E7ED;border-radius:5px;background-color:#fff"><div style="display:flex;justify-content:space-between;align-items:center;padding:20px"><div style="display:flex;justify-content:center;align-items:center"><div style="width:50px;height:50px;border-radius:50%;margin-right:20px"><img src="{avatar}" alt="头像" style="width:100%;height:100%;border-radius:50%;box-shadow:0 0 10px rgba(0,0,0,.4)"></div><div style="font-size:20px">{nickname}</div></div><div style="color:#999;font-size:15px">{time}</div></div><hr style="background-color:#DCDFE6;height:1px;border:none;margin:0"><div style="padding:20px">{content}</div></div></div><div style="display:flex;justify-content:space-around;align-items:center;margin:2rem 0"><a href="{toUrl}"><div class="butt_to" style="width:200px;height:50px;line-height:50px;text-align:center;font-size:20px;font-weight:bold;color:#333;background:#fff;border-radius:1rem;margin:0 auto">前往查看</div></a></div><div style="text-align:center;padding-bottom:1rem;font-size:15px">此为系统邮件，请勿回复。</div></div></div></body></html>', '["avatar","nickname","time","content","toUrl"]', 0, '有新留言时通知站长', '1', NOW(), '1', NOW(), 0);
